    let notes = query(NOTE_COUNT_SQL, &[])?;
    let notes = notes
        .pointer("/0/0")
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    Ok(serde_json::json!({ "existed": existed, "notes": notes }).to_string())
}

